    chip(c, '凑友希那 · ykn', 300, 940, { size: 40, bg: '#881188', color: '#fff' }); chip(c, '冰川纱夜 · sayo', 780, 940, { size: 40, bg: '#00aabb', color: '#fff' });
    // line 3: a brief soft sparkle around them (their kind side)
